    $effectMeta = \App\Services\SurpriseGameService::allPowerUpOptions();
    $currentEffect = $session->currentCard ? ($effectMeta[$session->currentCard->power_up_code ?? 'blank'] ?? $effectMeta['blank']) : null;
    $question = $session->currentCard?->question;
    $correctAnswer = $question?->question_type === 'multiple_answer'
        ? collect($question->options['correct_answers'] ?? [$question->correct_answer])->join(', ')
        : $question?->correct_answer;
    $timerIsPaused = (bool) $session->currentCard?->timer_paused_at;
    $timerInitialSeconds = $session->currentCard?->card_type === 'question' && $session->question_time_limit && $session->currentCard->revealed_at
        ? ($timerIsPaused
            ? (int) $session->currentCard->timer_remaining_seconds
            : max(0, $session->currentCard->revealed_at->copy()->addSeconds($session->question_time_limit)->getTimestamp() - now()->getTimestamp()))
        : null;
    $timerDeadlineMs = $timerInitialSeconds !== null && ! $timerIsPaused
        ? now()->addSeconds($timerInitialSeconds)->valueOf()
        : null;
    $questionType = $question?->question_type;
    $questionOptions = $questionType === 'multiple_answer'
        ? collect($question?->options['choices'] ?? [])
        : collect($question?->options ?? []);
    if ($questionType === 'true_false') {
        $questionOptions = collect([['key' => 'T', 'text' => 'Benar'], ['key' => 'F', 'text' => 'Salah']]);
    }
    $correctKeys = $questionType === 'multiple_answer'
        ? collect($question?->options['correct_answers'] ?? [])->map(fn ($key) => strtoupper((string) $key))->all()
        : [strtoupper((string) $question?->correct_answer)];
    $shortAnswers = $questionType === 'short_answer'
        ? ($question?->options['answers'] ?? [$question?->correct_answer])
        : [];
    $winnerScore = $session->status === 'finished' ? $session->teams->max('score') : null;
    $reviewQuestions = $session->status === 'finished'
        ? $session->cards->where('card_type', 'question')->map(function ($card) {
            $reviewQuestion = $card->question;
            return [
                'position' => $card->position,
                'question' => $reviewQuestion->question_text,
                'type' => $reviewQuestion->question_type,
                'options' => $reviewQuestion->options,
                'correct_answer' => $reviewQuestion->correct_answer,
                'image_url' => $reviewQuestion->image_url ? asset($reviewQuestion->image_url) : null,
            ];
        })->values()
        : collect();
