<script>
const revealAnswerButton=document.getElementById('reveal-answer');const answerPanel=document.getElementById('answer-panel');const questionActions=document.getElementById('question-actions');const gradingActions=document.getElementById('grading-actions');let timerId=null;let timedOut=false;
function stopQuestionTimer(){if(timerId){clearInterval(timerId);timerId=null;}}
function expireQuestion(){if(timedOut)return;timedOut=true;stopQuestionTimer();document.getElementById('question-content').hidden=true;document.getElementById('timeout-message').hidden=false;const timer=document.getElementById('question-timer');if(timer){timer.textContent='00:00';timer.classList.add('danger');}setTimeout(()=>{fetch(@json(route('surprise.cards.timeout', [$session, $session->currentCard])),{method:'POST',headers:{'X-CSRF-TOKEN':@json(csrf_token()),'Accept':'application/json'}}).finally(()=>window.location.reload());},5000);}
revealAnswerButton.addEventListener('click',()=>{if(timedOut)return;stopQuestionTimer();document.getElementById('question-content').classList.add('answer-revealed');if(answerPanel)answerPanel.hidden=false;questionActions.hidden=true;gradingActions.hidden=false;});
let timerIsPaused=@json($timerIsPaused),timerDeadline=@json($timerDeadlineMs);const timerInitialSeconds=@json($timerInitialSeconds),timerElement=document.getElementById('question-timer');const formatTimer=seconds=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;function startQuestionTimer(seconds){if(!timerElement)return;stopQuestionTimer();timerIsPaused=false;timerDeadline=Date.now()+seconds*1000;timerElement.classList.remove('is-paused');const tick=()=>{const remaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));timerElement.textContent=formatTimer(remaining);timerElement.classList.toggle('danger',remaining<=10);if(remaining<=0)expireQuestion();};tick();if(!timedOut)timerId=setInterval(tick,250);}if(timerInitialSeconds!==null&&timerElement){timerElement.textContent=formatTimer(timerInitialSeconds);if(!timerIsPaused&&timerDeadline)startQuestionTimer(timerInitialSeconds);}
const timerRoutes={pause:@json(route('surprise.cards.pause-timer', [$session, $session->currentCard])),resume:@json(route('surprise.cards.resume-timer', [$session, $session->currentCard]))};document.querySelector('[data-timer-control]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');if(button.disabled)return;const wasPaused=timerIsPaused;stopQuestionTimer();button.disabled=true;try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error();const data=await response.json(),remaining=Number(data.remaining_seconds||0);timerIsPaused=Boolean(data.timer_paused);timerElement.textContent=formatTimer(remaining);timerElement.classList.toggle('is-paused',timerIsPaused);timerElement.classList.remove('danger');if(timerIsPaused){form.action=timerRoutes.resume;button.textContent='▶ Lanjutkan Timer';}else{form.action=timerRoutes.pause;button.textContent='Ⅱ Jeda Timer';startQuestionTimer(remaining);}button.disabled=false;}catch(error){if(!wasPaused&&timerElement){const remaining=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));if(remaining>0)startQuestionTimer(remaining);}button.disabled=false;}});
function syncTimerControlIcon(){const form=document.querySelector('[data-timer-control]'),button=form?.querySelector('button');if(!form||!button||button.querySelector('svg'))return;const resume=form.action.includes('/resume-timer');button.className='timer-control';button.setAttribute('aria-label',resume?'Lanjutkan timer':'Jeda timer');button.title=button.getAttribute('aria-label');button.innerHTML=resume?'<svg class="btn-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7z" fill="currentColor" stroke="none"/></svg>':'<svg class="btn-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 5v14M17 5v14"/></svg>';}syncTimerControlIcon();const timerControlButton=document.querySelector('[data-timer-control] button');if(timerControlButton)new MutationObserver(syncTimerControlIcon).observe(timerControlButton,{childList:true});
</script>
