@if($session->status === 'finished' && $reviewQuestions->isNotEmpty())
<script>
const reviewQuestions=@json($reviewQuestions);let reviewIndex=0;const reviewSection=document.getElementById('review-section');const reviewQuestion=document.getElementById('review-question');const reviewImage=document.getElementById('review-image');const reviewOptions=document.getElementById('review-options');const reviewAnswer=document.getElementById('review-answer');const reviewPrevious=document.getElementById('review-previous');const reviewNext=document.getElementById('review-next');
function reviewOption(key,text,correct){const item=document.createElement('div');item.className=`question-option ${correct?'is-correct':''}`;const badge=document.createElement('span');badge.className='option-key';badge.textContent=key;item.append(badge,document.createTextNode(text));return item;}
function renderReview(){const item=reviewQuestions[reviewIndex];reviewQuestion.innerHTML=item.question||'';document.getElementById('review-count').textContent=`Soal ${reviewIndex+1} dari ${reviewQuestions.length} · Kartu ${item.position}`;reviewOptions.innerHTML='';reviewAnswer.innerHTML='';const type=item.type;const options=type==='multiple_answer'?(item.options?.choices||[]):(Array.isArray(item.options)?item.options:[]);if(['multiple_choice','multiple_answer','true_false'].includes(type)){const correct=type==='multiple_answer'?(item.options?.correct_answers||[]):[item.correct_answer];options.forEach(option=>{const isCorrect=correct.map(String).map(value=>value.toUpperCase()).includes(String(option.key).toUpperCase());reviewOptions.appendChild(reviewOption(option.key,option.text,isCorrect));});reviewAnswer.hidden=true;}else{reviewOptions.innerHTML='';const answers=item.options?.answers||[item.correct_answer];reviewAnswer.hidden=false;reviewAnswer.innerHTML='<h3>Kunci jawaban</h3><p></p>';reviewAnswer.querySelector('p').textContent=answers.filter(Boolean).join(' / ');}reviewImage.onerror=()=>{reviewImage.hidden=true;reviewImage.removeAttribute('src');};if(item.image_url){reviewImage.src=item.image_url;reviewImage.hidden=false;}else{reviewImage.hidden=true;reviewImage.removeAttribute('src');}reviewPrevious.disabled=reviewIndex===0;reviewNext.disabled=reviewIndex===reviewQuestions.length-1;}
document.getElementById('open-review-section').addEventListener('click',()=>{reviewIndex=0;renderReview();reviewSection.hidden=false;reviewSection.scrollIntoView({behavior:'smooth',block:'start'});});reviewPrevious.addEventListener('click',()=>{if(reviewIndex>0){reviewIndex--;renderReview();}});reviewNext.addEventListener('click',()=>{if(reviewIndex<reviewQuestions.length-1){reviewIndex++;renderReview();}});
</script>
