<script>
let qgameAudioContext=null;function playAnswerFeedback(kind){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;if(!qgameAudioContext||qgameAudioContext.state==='closed')qgameAudioContext=new AudioContext();const context=qgameAudioContext;if(context.state==='suspended')context.resume();const start=context.currentTime+.02,notes=kind==='correct'?[523.25,659.25,783.99]:[329.63,392,329.63];notes.forEach((frequency,index)=>{const oscillator=context.createOscillator(),gain=context.createGain(),time=start+index*(kind==='correct'?.075:.12);oscillator.type=kind==='correct'?'triangle':'sine';oscillator.frequency.setValueAtTime(frequency,time);gain.gain.setValueAtTime(.0001,time);gain.gain.exponentialRampToValueAtTime(kind==='correct'?.14:.1,time+.012);gain.gain.exponentialRampToValueAtTime(.0001,time+(kind==='correct'?.24:.18));oscillator.connect(gain).connect(context.destination);oscillator.start(time);oscillator.stop(time+(kind==='correct'?.26:.2));});}
document.querySelectorAll('[data-answer-feedback] button').forEach(button=>button.addEventListener('click',()=>playAnswerFeedback(button.closest('[data-answer-feedback]').dataset.answerFeedback),{once:true}));
document.querySelectorAll('form[action*="/surprise/sessions/"]:not([data-timer-control])').forEach(form=>form.addEventListener('submit',async event=>{if(form.dataset.pending)return event.preventDefault();event.preventDefault();form.dataset.pending='true';form.querySelectorAll('button').forEach(button=>button.disabled=true);const card=form.closest('.cards form')?.querySelector('.card');if(card)card.classList.add('is-pending');const backdrop=form.closest('.modal-backdrop');if(backdrop)backdrop.classList.add('is-leaving');try{const response=await fetch(form.action,{method:form.method||'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error('Aksi tidak dapat disimpan.');window.location.reload();}catch(error){form.dataset.pending='';form.querySelectorAll('button').forEach(button=>button.disabled=false);if(card)card.classList.remove('is-pending');if(backdrop)backdrop.classList.remove('is-leaving');window.location.reload();}}));
</script>
