<script>
function isSurpriseFullscreen(){return Boolean(document.fullscreenElement||document.webkitFullscreenElement);}function updateSurpriseFullscreenButton(){const button=document.getElementById('surprise-fullscreen');if(!button)return;const active=isSurpriseFullscreen();button.classList.toggle('is-fullscreen',active);button.setAttribute('aria-label',active?'Keluar dari layar penuh':'Layar penuh');button.title=button.getAttribute('aria-label');}function toggleSurpriseFullscreen(){if(isSurpriseFullscreen()){(document.exitFullscreen||document.webkitExitFullscreen)?.call(document);sessionStorage.removeItem('qgame-surprise-fullscreen');return;}sessionStorage.setItem('qgame-surprise-fullscreen','1');const root=document.documentElement;(root.requestFullscreen||root.webkitRequestFullscreen)?.call(root)?.catch?.(()=>{});}document.getElementById('surprise-fullscreen')?.addEventListener('click',toggleSurpriseFullscreen);document.addEventListener('fullscreenchange',updateSurpriseFullscreenButton);document.addEventListener('webkitfullscreenchange',updateSurpriseFullscreenButton);updateSurpriseFullscreenButton();if(sessionStorage.getItem('qgame-surprise-fullscreen')==='1'&&!isSurpriseFullscreen()){window.setTimeout(()=>{const root=document.documentElement;(root.requestFullscreen||root.webkitRequestFullscreen)?.call(root)?.catch?.(()=>{});},120);}
</script>
